import{_ as e,o as i,c as a,ak as d}from"./chunks/framework.B8jO0odJ.js";const g=JSON.parse(`{"title":"Chainy team delegation and work packets","description":"Assignments below are made by name at the user's request. They do not require or create GitHub accounts, notify teammates, or claim that a teammate has accepted a deadline. Sh","frontmatter":{"title":"Chainy team delegation and work packets","description":"Assignments below are made by name at the user's request. They do not require or create GitHub accounts, notify teammates, or claim that a teammate has accepted a deadline. Sh","source":"docs/team-delegation.md","category":"Delivery & team","sourceUpdated":null,"outline":[2,3]},"headers":[],"relativePath":"content/docs/team-delegation.md","filePath":"content/docs/team-delegation.md"}`),r={name:"content/docs/team-delegation.md"};function n(s,t,o,l,h,c){return i(),a("div",null,[...t[0]||(t[0]=[d('<div><h1 id="chainy-team-delegation-and-work-packets">Chainy team delegation and work packets<a class="header-anchor" href="#chainy-team-delegation-and-work-packets" aria-label="Link to this section">​</a></h1><p>Assignments below are made by name at the user&#39;s request. They do not require or create GitHub accounts, notify teammates, or claim that a teammate has accepted a deadline. Sherwin communicates the plan and records updates from members without GitHub access.</p><p>One owner delivers each task; support contributes bounded inputs; the reviewer checks the acceptance evidence. Reviewers must read/test the artifact and disclose limits of their expertise. Sean&#39;s educational review is not a substitute for an external subject/educator review where needed.</p><h2 id="individual-responsibilities-and-first-handoff">Individual responsibilities and first handoff<a class="header-anchor" href="#individual-responsibilities-and-first-handoff" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Member</th><th>Responsibility</th><th>First concrete handoff</th></tr></thead><tbody><tr><td>Sherwin Limosnero</td><td>Scope, site coordination, AI prototype/level and external evidence importer</td><td>Review GDD decisions, confirm site contact and device list, define classifier examples</td></tr><tr><td>Christian Jude Villaber</td><td>Unity Android foundation, SQLite, construction/blockchain mechanics and integration</td><td>Pin toolchain and install the first APK; validate SQLite/export on-device</td></tr><tr><td>Sean Matthew Narvaez</td><td>Manuscript, related literature, methodology, instruments and pilot evidence</td><td>Draft Chapters I–II and research matrix; request the exact school instrument</td></tr><tr><td>Luis Cabrido III</td><td>Art direction, reusable assets and licensing</td><td>Deliver a small low-poly sample kit and mobile import notes to Christian/Miguel</td></tr><tr><td>Miguel De Leon</td><td>Menus/HUD/profile/export UI, test execution and document support</td><td>Wireframe learner-code/map/workbench/export screens; prepare test records</td></tr></tbody></table><p>Sherwin&#39;s AI and importer coding assignments reduce Christian&#39;s implementation bottleneck, but require technical review. Miguel executes routine QA; Christian fixes and reviews technical failures. Luis owns art assets, while Miguel owns UI implementation. Sean owns manuscript prose; Miguel can prepare figures/references without editing the same section concurrently.</p><h2 id="task-packets">Task packets<a class="header-anchor" href="#task-packets" aria-label="Link to this section">​</a></h2><p>Each linked issue contains dependencies, target date and detailed acceptance checks. The table retains original published targets as history. Use the revised October 8 forecast at the end of this document for current local planning; the user-confirmed pre-final date is November 21.</p><table><thead><tr><th>Task</th><th>Owner</th><th>Support</th><th>Reviewer</th><th>Deliverable</th><th>Target</th></tr></thead><tbody><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/2">CH-01</a></td><td>Sherwin Limosnero</td><td>Sean Matthew Narvaez</td><td>Sean Matthew Narvaez</td><td>Decision log, available-hours record and school evidence checklist</td><td>2026-10-07</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/3">CH-02</a></td><td>Sherwin Limosnero</td><td>Sean Matthew Narvaez, Luis Cabrido III, Miguel De Leon</td><td>Christian Jude Villaber</td><td>Reviewed GDD with level rules and content caps</td><td>2026-10-09</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/4">CH-03</a></td><td>Christian Jude Villaber</td><td>Miguel De Leon</td><td>Sherwin Limosnero</td><td>Pinned build configuration, source link and device APK</td><td>2026-10-09</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/5">CH-04</a></td><td>Christian Jude Villaber</td><td>Miguel De Leon</td><td>Sherwin Limosnero</td><td>SQLite adapter spike, schema and export proof</td><td>2026-10-11</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/6">CH-05</a></td><td>Christian Jude Villaber</td><td>Luis Cabrido III, Miguel De Leon</td><td>Sherwin Limosnero</td><td>Free-placement construction scene and rule checks</td><td>2026-10-16</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/7">CH-06</a></td><td>Christian Jude Villaber</td><td>Miguel De Leon, Sean Matthew Narvaez</td><td>Sherwin Limosnero</td><td>Level 1 playable loop with saved checkpoint</td><td>2026-10-18</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/8">CH-07</a></td><td>Christian Jude Villaber</td><td>Sherwin Limosnero, Luis Cabrido III</td><td>Sean Matthew Narvaez</td><td>Tamper and three-replica mission with explained limits</td><td>2026-10-25</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/9">CH-08</a></td><td>Sherwin Limosnero</td><td>Sean Matthew Narvaez</td><td>Christian Jude Villaber</td><td>Example-trained classifier with held-out test cases</td><td>2026-10-18</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/10">CH-09</a></td><td>Sherwin Limosnero</td><td>Christian Jude Villaber, Miguel De Leon</td><td>Sean Matthew Narvaez</td><td>AI level and capped agent mission</td><td>2026-11-01</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/11">CH-10</a></td><td>Luis Cabrido III</td><td>Miguel De Leon</td><td>Sherwin Limosnero</td><td>Reusable asset kit, mobile imports and license ledger</td><td>2026-10-25</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/12">CH-11</a></td><td>Sherwin Limosnero</td><td>Christian Jude Villaber, Sean Matthew Narvaez</td><td>Christian Jude Villaber</td><td>Staff importer and versioned evidence package contract</td><td>2026-10-25</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/13">CH-12</a></td><td>Sean Matthew Narvaez</td><td>Sherwin Limosnero</td><td>Sherwin Limosnero</td><td>Reviewed protocol, instruments and data-handling agreement</td><td>2026-10-18</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/14">CH-13</a></td><td>Christian Jude Villaber</td><td>Sherwin Limosnero, Luis Cabrido III, Miguel De Leon</td><td>Sherwin Limosnero</td><td>Integrated APK with all core mechanics</td><td>2026-11-06</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/15">CH-14</a></td><td>Miguel De Leon</td><td>Christian Jude Villaber, Luis Cabrido III</td><td>Christian Jude Villaber</td><td>Recorded device test matrix and recovery evidence</td><td>2026-11-07</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/16">CH-15</a></td><td>Sean Matthew Narvaez</td><td>Sherwin Limosnero, Miguel De Leon</td><td>Sherwin Limosnero</td><td>Approved pilot records and de-identified analysis inputs</td><td>2026-11-13</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/17">CH-16</a></td><td>Sean Matthew Narvaez</td><td>Miguel De Leon</td><td>Sherwin Limosnero</td><td>Complete formatted manuscript and evidence index</td><td>2026-11-16</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/18">CH-17</a></td><td>Sherwin Limosnero</td><td>Christian Jude Villaber, Sean Matthew Narvaez, Luis Cabrido III, Miguel De Leon</td><td>Sean Matthew Narvaez</td><td>Rehearsal record, demonstration APK and recovery kit</td><td>2026-11-20</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/19">CH-18</a></td><td>Sherwin Limosnero</td><td>Sean Matthew Narvaez</td><td>Sean Matthew Narvaez</td><td>Panel-action log and revised scope/schedule</td><td>2026-11-27</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/20">CH-19</a></td><td>Sean Matthew Narvaez</td><td>Miguel De Leon, Christian Jude Villaber</td><td>Sherwin Limosnero</td><td>Final approved study and QA evidence</td><td>2026-12-18</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/21">CH-20</a></td><td>Christian Jude Villaber</td><td>Sean Matthew Narvaez, Luis Cabrido III, Miguel De Leon</td><td>Sherwin Limosnero</td><td>Signed final package and release/handover documentation</td><td>2027-02-08</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/22">CH-21</a></td><td>Sherwin Limosnero</td><td>Christian Jude Villaber, Sean Matthew Narvaez, Luis Cabrido III, Miguel De Leon</td><td>Sean Matthew Narvaez</td><td>Final defense disposition and handover record</td><td>2027-04-09</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/24">CH-22</a></td><td>Sean Matthew Narvaez</td><td>Miguel De Leon</td><td>Sherwin Limosnero</td><td>Chapters I–II with verified references</td><td>2026-10-14</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/25">CH-23</a></td><td>Sean Matthew Narvaez</td><td>Christian Jude Villaber</td><td>Sherwin Limosnero</td><td>Chapter III, design figures and reviewed instruments</td><td>2026-10-16</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/26">CH-24</a></td><td>Sherwin Limosnero</td><td>Sean Matthew Narvaez</td><td>Sean Matthew Narvaez</td><td>Actual pilot contact, site documents and booking record</td><td>2026-10-12</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/27">CH-25</a></td><td>Sean Matthew Narvaez</td><td>Miguel De Leon, Christian Jude Villaber</td><td>Sherwin Limosnero</td><td>Chapters IV–V, front matter and appendices A–M</td><td>2026-11-16</td></tr><tr><td><a href="https://github.com/Kamiyon-Studio/Chainy/issues/28">CH-26</a></td><td>Miguel De Leon</td><td>Luis Cabrido III, Christian Jude Villaber</td><td>Sherwin Limosnero</td><td>Menus, profile entry, HUD and teacher-export UI</td><td>2026-10-16</td></tr></tbody></table><h2 id="capacity-and-review-boundaries">Capacity and review boundaries<a class="header-anchor" href="#capacity-and-review-boundaries" aria-label="Link to this section">​</a></h2><p>The reported 5–8 hours daily is a provisional upper bound, not verified sustainable availability. The estimates below are rough owner focus-hours for tasks due before defense; they exclude support/review time, classes, external waiting and unexpected rework. They are planning hypotheses, not promises.</p><table><thead><tr><th>Owner</th><th>Estimated pre-final focus-hours</th></tr></thead><tbody><tr><td>Sherwin Limosnero</td><td>82–140</td></tr><tr><td>Christian Jude Villaber</td><td>104–184</td></tr><tr><td>Sean Matthew Narvaez</td><td>108–180</td></tr><tr><td>Luis Cabrido III</td><td>30–50</td></tr><tr><td>Miguel De Leon</td><td>36–60</td></tr></tbody></table><p>Reserve integration and rehearsal time and re-estimate after the first real device spike. Documentation is also critical-path work: Sean needs actual results early enough for Chapters IV–V. A large apparent hour budget is not a guarantee that a dependency or site booking will finish.</p><h2 id="handoff-and-daily-operation">Handoff and daily operation<a class="header-anchor" href="#handoff-and-daily-operation" aria-label="Link to this section">​</a></h2><p>Deliver source/document link, version/build, completed acceptance checks, known gaps and next dependency. Do not send “done” without the artifact. Sherwin updates the board from short team check-ins; a named Lead is sufficient until members choose to obtain GitHub accounts.</p><p>Work on separate prefabs/scenes or document sections to avoid overwrites. Christian owns bootstrap/integration scenes; Miguel supplies UI prefabs; Luis supplies model prefabs; Sherwin supplies pure AI/agent rule modules; Sean supplies versioned instructional text and instruments. Agree interfaces before integration.</p><p>The documentation package is the first deliverable. Use a proposed two-day review window to settle scope and contracts before production, while keeping the October 9–11 technical-spike target visible. No recurring messages or autonomous task execution are scheduled by this document.</p><h2 id="october-8-workload-balancing-proposal">October 8 workload balancing proposal<a class="header-anchor" href="#october-8-workload-balancing-proposal" aria-label="Link to this section">​</a></h2><p>Updated after the user&#39;s explicit answer: actual weekly availability is unknown; create a balanced planning estimate. Use <strong>520 person-hours through November 20</strong> as a proposed allocation budget, including 60 hours of contingency. This replaces the previous 355–530-hour allocation envelope for dispatch planning. Neither figure is a measured task estimate or evidence that the team can deliver within it. The original owner-only estimates above excluded support/review and are retained as history, not added to this budget.</p><p>Preserve existing issue Leads and reviewers. Balance hands-on work by delegating bounded outputs that match experience, rather than assuming that art, research and technical hours are interchangeable. Christian retains toolchain, schema, integration and technical signoff. Sean retains research interpretation. Sherwin owns scope/site decisions. All allocations below are unconfirmed planning estimates; no external issue/card dates or assignments were changed.</p><h3 id="estimated-hours-by-work-type">Estimated hours by work type<a class="header-anchor" href="#estimated-hours-by-work-type" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Member</th><th style="text-align:right;">Primary production</th><th style="text-align:right;">Review and integration</th><th style="text-align:right;">QA and evidence checks</th><th style="text-align:right;">Pilot preparation/session support</th><th style="text-align:right;">Manuscript, guides and rehearsal</th><th style="text-align:right;">Contingency</th><th style="text-align:right;">Total</th></tr></thead><tbody><tr><td>Sherwin Limosnero</td><td style="text-align:right;">44</td><td style="text-align:right;">12</td><td style="text-align:right;">10</td><td style="text-align:right;">8</td><td style="text-align:right;">18</td><td style="text-align:right;">12</td><td style="text-align:right;">104</td></tr><tr><td>Christian Jude Villaber</td><td style="text-align:right;">52</td><td style="text-align:right;">18</td><td style="text-align:right;">10</td><td style="text-align:right;">6</td><td style="text-align:right;">10</td><td style="text-align:right;">12</td><td style="text-align:right;">108</td></tr><tr><td>Sean Matthew Narvaez</td><td style="text-align:right;">36</td><td style="text-align:right;">10</td><td style="text-align:right;">8</td><td style="text-align:right;">12</td><td style="text-align:right;">26</td><td style="text-align:right;">12</td><td style="text-align:right;">104</td></tr><tr><td>Luis Cabrido III</td><td style="text-align:right;">42</td><td style="text-align:right;">10</td><td style="text-align:right;">12</td><td style="text-align:right;">8</td><td style="text-align:right;">16</td><td style="text-align:right;">12</td><td style="text-align:right;">100</td></tr><tr><td>Miguel De Leon</td><td style="text-align:right;">38</td><td style="text-align:right;">12</td><td style="text-align:right;">18</td><td style="text-align:right;">8</td><td style="text-align:right;">16</td><td style="text-align:right;">12</td><td style="text-align:right;">104</td></tr><tr><td>Team</td><td style="text-align:right;">212</td><td style="text-align:right;">62</td><td style="text-align:right;">58</td><td style="text-align:right;">42</td><td style="text-align:right;">86</td><td style="text-align:right;">60</td><td style="text-align:right;">520</td></tr></tbody></table><p>These categories are mutually exclusive allocations; count a review or integration hour once. Primary production means Sherwin: AI/agent/importer and scope coordination; Christian: Android/SQLite/construction/blockchain; Sean: literature, methods, instruments and initial manuscript; Luis: reusable art, asset import, isolated scene dressing and figures; Miguel: UI, synthetic fixtures and document assembly. The manuscript column covers final assembly, guides and rehearsal in addition to Sean&#39;s early authorship budget. Pilot support includes preparation and approved on-site work only if booking succeeds. Travel time and cost are unknown and must be charged to this budget or explicitly reforecast before booking; they are not free extra capacity.</p><h3 id="calendar-allocation-focus-hours-including-the-contingency-above">Calendar allocation (focus-hours, including the contingency above)<a class="header-anchor" href="#calendar-allocation-focus-hours-including-the-contingency-above" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Member</th><th style="text-align:right;">Oct 8–14</th><th style="text-align:right;">Oct 15–21</th><th style="text-align:right;">Oct 22–28</th><th style="text-align:right;">Oct 29–Nov 4</th><th style="text-align:right;">Nov 5–11</th><th style="text-align:right;">Nov 12–20 (9 days)</th><th style="text-align:right;">Total</th></tr></thead><tbody><tr><td>Sherwin</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">16</td><td style="text-align:right;">16</td><td style="text-align:right;">104</td></tr><tr><td>Christian</td><td style="text-align:right;">20</td><td style="text-align:right;">20</td><td style="text-align:right;">20</td><td style="text-align:right;">18</td><td style="text-align:right;">14</td><td style="text-align:right;">16</td><td style="text-align:right;">108</td></tr><tr><td>Sean</td><td style="text-align:right;">16</td><td style="text-align:right;">16</td><td style="text-align:right;">16</td><td style="text-align:right;">18</td><td style="text-align:right;">20</td><td style="text-align:right;">18</td><td style="text-align:right;">104</td></tr><tr><td>Luis</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">16</td><td style="text-align:right;">14</td><td style="text-align:right;">16</td><td style="text-align:right;">100</td></tr><tr><td>Miguel</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">18</td><td style="text-align:right;">16</td><td style="text-align:right;">16</td><td style="text-align:right;">104</td></tr><tr><td>Team</td><td style="text-align:right;">90</td><td style="text-align:right;">90</td><td style="text-align:right;">90</td><td style="text-align:right;">88</td><td style="text-align:right;">80</td><td style="text-align:right;">82</td><td style="text-align:right;">520</td></tr></tbody></table><p>Reserve two contingency hours per person in each of the six blocks (12 each). Do not schedule those hours as new features. The final block is nine days, not a seven-day week. November 21 is defense day and is outside this focus-hour budget. At each weekly review, record actual focus/review hours, remaining work and blockers against these estimates; availability remains unknown until each member validates it. A balanced table cannot establish feasibility.</p><h3 id="bounded-handoffs-and-accountable-review">Bounded handoffs and accountable review<a class="header-anchor" href="#bounded-handoffs-and-accountable-review" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Person</th><th>Additional work that balances effort</th><th>Acceptance reviewer</th></tr></thead><tbody><tr><td>Sherwin</td><td>CH-08/09 pure classifier/agent modules; CH-11 importer semantics; CH-24 tentative school coordination; scope and defense evidence map</td><td>Christian for code; Sean for site/evidence records</td></tr><tr><td>Christian</td><td>CH-03/04 build/store spike; CH-05/07 core rules; shared-scene integration and signed update verification</td><td>Sherwin, with disclosed technical-review limits</td></tr><tr><td>Sean</td><td>CH-22/23/25 research prose and interpretation; versioned instructional copy; approved instruments and pilot records</td><td>Sherwin; educator/adviser input where required</td></tr><tr><td>Luis</td><td>CH-10 reusable prefabs/import manifests; isolated level dressing; GDD/manuscript figures and captions; visual readability QA; supervised pilot logistics</td><td>Christian for asset integration, Miguel for UI fit, Sean for evidence captions</td></tr><tr><td>Miguel</td><td>CH-26 screens against stable mocks; CH-11 synthetic duplicate/conflict packages; CH-14 device execution; appendix/guide assembly; rehearsal recording</td><td>Christian for tests/UI integration; Sean for manuscript assembly</td></tr></tbody></table><p>Luis does not inherit SQLite debugging; Miguel does not waive failures; agents do not fabricate research results. Source handoffs include version, owned files, actual checks, gaps and reviewer disposition. Issue Leads remain accountable for delegated outputs. No teammate notification is implied.</p><p><strong>Protected revised forecast:</strong> integrate a beta candidate by October 30; test October 31–November 2; tentative school beta November 3–6 at Tambunan National High School, Marinduque; fixes and evidence analysis November 7–13; manuscript November 16; rehearsal November 17–20; <strong>pre-final November 21, 2026</strong>. Site attendance, dates, devices, permissions and participant count remain unconfirmed. The original November 6 integration / November 8–13 learner-session forecast is superseded locally; original issue targets in the table above remain publication history.</p><p>Scope verdict: <strong>validate first</strong>. The 520-hour total is a balanced planning envelope, not measured capacity. The later October 8 approved scope replaces free construction/exploration with a tappable map and bounded ordering/linking, retains guided local replicas, a prototype-validated classifier and a short grid agent, and adds selected foundational Web3 content. Reuse released construction effort for the lesson shell, beginner content and accessibility checks; do not automatically spend it on extra features. Named hour totals remain estimates pending production timing. If APK/SQLite evidence is absent October 11, or one complete lesson is not accepted October 18, reforecast immediately. If safe school readiness fails November 2, escalate booking/evidence implications instead of using an untested build or assuming a repeat visit. Preserve integration, QA and rehearsal allocations. Earlier task labels in this document mirror the published board and require deliberate synchronization; the <a href="/Chainy-Docs/content/docs/project-baseline.html#governing-mission-and-scope">baseline</a> governs current acceptance.</p></div>',1)])])}const p=e(r,[["render",n]]);export{g as __pageData,p as default};
